 @Autowired PermanentCheckinService qr;@Autowired PublicClubService clubs;@Autowired PublicReservationService bookings;@Autowired ClubCustomerService customers;@Autowired ClubPublicSiteRepository sites;@Autowired ClubPublicSlugRepository slugs;@Autowired ClubCustomerRepository directory;@Autowired ClubCustomerVisitRepository visits;@Autowired ClubReservationRequestRepository requests;@Autowired FacilityPermanentQrRepository qrs;@Autowired FacilityMobileLimitRepository limits;@Autowired FacilityQrChallengeRepository forms;@Autowired FacilityCustomerCheckinRepository checkins;@Autowired AcademyRunningSessionRepository sessions;@Autowired SessionStopQuoteRepository quotes;@Autowired SessionDiscountRequestRepository discounts;@Autowired com.arena.core.billing.AcademyPaymentRepository payments;@Autowired AcademyAuthorization auth;@Autowired AcademyPlayAreaRepository areas;@Autowired AcademySportRepository sports;@Autowired FacilityService facilities;@Autowired CustomerRepository tenants;@Autowired CustomerAccessService access;@Autowired RunningSessionService lifecycle;@Autowired EntityManagerFactory factory;@Autowired PlatformTransactionManager tm;
 TransactionTemplate tx;EntityManager em;AcademyAuthorization.Actor owner;Map<Long,CustomerEntity> tenantData;List<AcademySport> sportData;
 @BeforeEach void setup(){org.springframework.test.util.ReflectionTestUtils.setField(clubs,"websiteManagementEnabled",true);org.springframework.test.util.ReflectionTestUtils.setField(bookings,"reservationRequestsEnabled",true);org.springframework.test.util.ReflectionTestUtils.setField(clubs,"reservationRequestsEnabled",true);previewConfiguration("dev",false,false);tx=new TransactionTemplate(tm);em=org.springframework.orm.jpa.SharedEntityManagerCreator.createSharedEntityManager(factory);owner=actor(1,1,"OWNER");SessionCheckoutIntegrationTest.ACTOR.set(owner);when(auth.manage(any())).thenAnswer(i->{var a=SessionCheckoutIntegrationTest.ACTOR.get();if(!a.manager())throw new ArenaOpsException(ErrorCode.ACCESS_DENIED);return a;});when(auth.operations(any())).thenAnswer(i->{var a=SessionCheckoutIntegrationTest.ACTOR.get();if(!a.operations())throw new ArenaOpsException(ErrorCode.ACCESS_DENIED);return a;});
 tx.executeWithoutResult(t->{visits.deleteAll();requests.deleteAll();checkins.deleteAll();forms.deleteAll();limits.deleteAll();qrs.deleteAll();directory.deleteAll();quotes.deleteAll();discounts.deleteAll();payments.deleteAll();sessions.deleteAll();slugs.deleteAll();sites.deleteAll();em.createQuery("delete from AcademyPlayArea").executeUpdate();for(long id=1;id<=2;id++){var f=new AcademyPlayArea();f.setAcademyId(id);f.setSportId(id==1?11L:22L);f.setCode(id==1?"E1":"C1");f.setFacilityType(id==1?"ENGLISH":"COURT");f.setActive(true);f.setHourlyRate(new BigDecimal("220"));em.persist(f);em.flush();}});
 tenantData=new HashMap<>();for(long id=1;id<=2;id++){var c=CustomerEntity.builder().id(id).customerName("Tenant "+id).businessDisplayName(id==1?"Speed Club":"Court Club").publicPhone("+911234567890").trainingTimezone("Asia/Kolkata").accessAllowed(true).build();tenantData.put(id,c);}when(tenants.findById(anyLong())).thenAnswer(i->Optional.ofNullable(tenantData.get(i.getArgument(0))));when(tenants.findBillingCustomerForUpdate(anyLong())).thenAnswer(i->Optional.ofNullable(tenantData.get(i.getArgument(0))));when(access.isCustomerUsable(any())).thenAnswer(i->{CustomerEntity c=i.getArgument(0);return c!=null&&Boolean.TRUE.equals(c.getAccessAllowed());});
 sportData=new ArrayList<>();for(long id=1;id<=2;id++){var s=new AcademySport();s.setId(id==1?11L:22L);s.setAcademyId(id);s.setCatalogueCode(id==1?"SNOOKER":"BADMINTON");s.setName(id==1?"Snooker":"Badminton");s.setActive(true);s.setSessions(true);sportData.add(s);}when(sports.findById(anyLong())).thenAnswer(i->sportData.stream().filter(s->s.getId().equals(i.getArgument(0))).findFirst());when(sports.findByAcademyIdOrderByName(anyLong())).thenAnswer(i->sportData.stream().filter(s->s.getAcademyId().equals(i.getArgument(0))).toList());
 reset(areas);var facilityMock=org.springframework.test.util.AopTestUtils.<FacilityService>getUltimateTargetObject(facilities);reset(facilityMock);when(areas.findById(anyLong())).thenAnswer(i->Optional.ofNullable(em.find(AcademyPlayArea.class,i.getArgument(0))));when(areas.findByAcademyIdOrderByName(anyLong())).thenAnswer(i->em.createQuery("select f from AcademyPlayArea f where f.academyId=:a",AcademyPlayArea.class).setParameter("a",i.getArgument(0)).getResultList());when(areas.locked(anyLong(),anyLong())).thenAnswer(i->{AcademyPlayArea f=em.find(AcademyPlayArea.class,i.getArgument(1),LockModeType.PESSIMISTIC_WRITE);return f!=null&&f.getAcademyId().equals(i.getArgument(0))?Optional.of(f):Optional.empty();});doAnswer(i->areas.locked(i.getArgument(1),i.getArgument(2)).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND))).when(facilityMock).requireEligibleLocked(any(),anyLong(),anyLong());
 clubs.save(SessionCheckoutIntegrationTest.JWT,new Settings(-1L,"speed",true,false,true,LocalTime.of(0,0),LocalTime.of(23,59),List.of(30,60,90)));}
 @AfterEach void clear(){SessionCheckoutIntegrationTest.ACTOR.remove();}
 AcademyAuthorization.Actor actor(long id,long academy,String role){var u=AppUserEntity.builder().id(id).username("user"+id).customerId(academy).isActive(true).build();return new AcademyAuthorization.Actor(u,null,Set.of(role));}
 Long facility(long academy){return tx.execute(t->em.createQuery("select f.id from AcademyPlayArea f where f.academyId=:a",Long.class).setParameter("a",academy).getSingleResult());}
 Challenge issue(){return qr.issue(SessionCheckoutIntegrationTest.JWT,facility(1));}
 Submission submission(Challenge q,String name,String mobile){var info=qr.inspect("speed",q.token());tx.executeWithoutResult(t->{var f=forms.locked(ClubCustomerService.hash(info.formToken())).orElseThrow();f.setCreatedAt(Instant.now().minusSeconds(3));forms.save(f);});return new Submission(q.token(),name,mobile,true,UUID.randomUUID(),info.formToken(),"");}
 FacilityCustomerCheckin accept(Challenge q,String name,String mobile){var r=submission(q,name,mobile);qr.submit("speed",r);return checkins.findByAcademyIdAndFacilityIdAndRequestId(1L,facility(1),r.requestId()).orElseThrow();}
 void reject(FacilityCustomerCheckin c){qr.cancel(SessionCheckoutIntegrationTest.JWT,c.getId());}
 LocalDateTime tomorrow(){return LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(1).atTime(12,0);}
 Booking booking(Long id,String mobile){return new Booking(UUID.randomUUID(),id,tomorrow(),60,"Guest",mobile,true,"");}
 @Test void permanentQrRemainsSameAndNonceRefreshDoesNotCount(){var a=issue();assertEquals(a.token(),issue().token());assertEquals("http://localhost:4200/check-in#"+a.token(),a.url());qr.inspect("speed",a.token());qr.inspect("speed",a.token());assertEquals(0,checkins.count());}
 @Test void onePendingAndIdempotentRetryDoNotAddAttempts(){var q=issue();var r=submission(q,"Guest","+919876543210");var first=qr.submit("speed",r);var retry=qr.submit("speed",r);assertEquals(first.status(),retry.status());assertTrue(Math.abs(Duration.between(first.expiresAt(),retry.expiresAt()).toNanos())<=1000);assertEquals(1,checkins.count());assertThrows(ArenaOpsException.class,()->qr.submit("speed",submission(q,"Other","+919876543211")));assertEquals(1,checkins.count());}
 @Test void twoAcceptedPerMobileThenThirdCreatesDurableCooldown(){var q=issue();reject(accept(q,"Guest","+919876543210"));reject(accept(q,"Guest","+919876543210"));assertThrows(PublicLimitException.class,()->qr.submit("speed",submission(q,"Guest","+919876543210")));assertEquals(2,checkins.count());assertTrue(limits.findAll().get(0).getBlockedUntil().isAfter(Instant.now().plusSeconds(1700)));}
 @Test void fourthAcceptedSuspendsQrOwnerResetAllowsOtherMobile(){var q=issue();for(int i=0;i<4;i++)reject(accept(q,"Guest "+i,"+91987654321"+i));assertTrue(qrs.findById(facility(1)).orElseThrow().getSuspendedUntil().isAfter(Instant.now()));assertThrows(PublicLimitException.class,()->qr.submit("speed",submission(q,"Another","+919876543219")));qr.clearCooldown(SessionCheckoutIntegrationTest.JWT,facility(1));assertNotNull(accept(q,"Another","+919876543219"));}
 @Test void manualQuickStartWorksDuringQrCooldown(){var q=issue();tx.executeWithoutResult(t->{var row=qrs.findById(facility(1)).orElseThrow();row.setSuspendedUntil(Instant.now().plusSeconds(1800));qrs.save(row);});assertEquals("STARTED",lifecycle.start(SessionCheckoutIntegrationTest.JWT,new RunningSessionContracts.Start(facility(1),"Manual")).status());}
 @Test void invalidMobileBotAndFastNonceDoNotCount(){var q=issue();var f=qr.inspect("speed",q.token());assertThrows(ArenaOpsException.class,()->qr.submit("speed",new Submission(q.token(),"Guest","123",true,UUID.randomUUID(),f.formToken(),"")));assertThrows(ArenaOpsException.class,()->qr.submit("speed",new Submission(q.token(),"Guest","+919876543210",true,UUID.randomUUID(),f.formToken(),"bot")));assertThrows(ArenaOpsException.class,()->qr.submit("speed",new Submission(q.token(),"Guest","+919876543210",true,UUID.randomUUID(),f.formToken(),"")));assertEquals(0,checkins.count());}
