 @Test void realSessionsCreateVisitsAndDifferentNamesOnSamePhoneStaySeparate(){var q=issue();var c=accept(q,"Ravi","+919876543210");var started=qr.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null));assertEquals(1,visits.count());assertEquals(1,customers.list(SessionCheckoutIntegrationTest.JWT,0).getContent().get(0).visitCount());assertThrows(ArenaOpsException.class,()->qr.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null)));tx.executeWithoutResult(t->{var s=sessions.findById(started.sessionId()).orElseThrow();s.setStatus("STOPPED");sessions.save(s);});var next=accept(q,"Ravi Kumar","+919876543210");qr.confirm(SessionCheckoutIntegrationTest.JWT,next.getId(),new Confirm(null));assertEquals(2,directory.count());assertEquals(2,visits.count());}
 @Test void customerCountsUseSessionsAcrossDaysAndDeletionScrubsWithoutRepricing(){var q=issue();var c=accept(q,"Guest","+919876543210");var s=qr.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null));var id=directory.findAll().get(0).getId();tx.executeWithoutResult(t->{var first=sessions.findById(s.sessionId()).orElseThrow();first.setStatus("STOPPED");first.setTotalAmount(new BigDecimal("57"));sessions.save(first);var visit=visits.findAll().get(0);visit.setStartedAt(Instant.now().minus(Duration.ofDays(1)));visits.save(visit);});var next=accept(q,"Guest","+919876543210");qr.confirm(SessionCheckoutIntegrationTest.JWT,next.getId(),new Confirm(null));var row=customers.list(SessionCheckoutIntegrationTest.JWT,0).getContent().get(0);assertEquals(2,row.visitCount());assertTrue(row.firstVisit().isBefore(row.lastVisit()));customers.forget(SessionCheckoutIntegrationTest.JWT,id);assertNull(directory.findById(id).orElseThrow().getMobile());assertNull(sessions.findById(s.sessionId()).orElseThrow().getPlayerName());assertEquals(0,new BigDecimal("57").compareTo(sessions.findById(s.sessionId()).orElseThrow().getTotalAmount()));}
