 @Test void bookingHoursAndSeparateSpamLimitsApply(){assertThrows(ArenaOpsException.class,()->bookings.request("speed",new Booking(UUID.randomUUID(),facility(1),tomorrow().withHour(23).withMinute(30),60,"Guest","+919876543210",true,"")));bookings.request("speed",booking(facility(1),"+919876543210"));bookings.request("speed",booking(facility(1),"+919876543210"));assertThrows(ArenaOpsException.class,()->bookings.request("speed",booking(facility(1),"+919876543210")));}
 @Test void simultaneousQrSubmissionsHaveOneActionableWinner()throws Exception{var q=issue();var a=submission(q,"One","+919876543210");var b=submission(q,"Two","+919876543211");var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);List<Future<Boolean>> tasks=new ArrayList<>();for(var r:List.of(a,b))tasks.add(pool.submit(()->{start.await();try{qr.submit("speed",r);return true;}catch(ArenaOpsException e){return false;}}));start.countDown();int wins=0;for(var f:tasks)if(f.get(10,TimeUnit.SECONDS))wins++;assertEquals(1,wins);assertEquals(1,checkins.count());}finally{pool.shutdownNow();}}
