 @Test void simultaneousStaffConfirmationRecordsOneSessionAndVisit()throws Exception{var c=accept(issue(),"Guest","+919876543210");var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);List<Future<Boolean>> tasks=new ArrayList<>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{SessionCheckoutIntegrationTest.ACTOR.set(owner);start.await();try{qr.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null));return true;}catch(ArenaOpsException e){return false;}finally{SessionCheckoutIntegrationTest.ACTOR.remove();}}));start.countDown();int wins=0;for(var f:tasks)if(f.get(10,TimeUnit.SECONDS))wins++;assertEquals(1,wins);assertEquals(1,sessions.count());assertEquals(1,visits.count());}finally{pool.shutdownNow();}}
